def extract(fpath):
    lines=open(fpath).read().splitlines()
    out=[]
    for i,line in enumerate(lines):
        if 'Your submission was CORRECT' in line:
            for j in range(i-1,max(0,i-20),-1):
                if '"role":"assistant"' in lines[j] and 'submit' in lines[j]:
                    m=re.search(r'"grid":\s*(\[\[.*?\]\])', lines[j])
                    if m: out.append(m.group(1))
                    break
            # find instance start with task-94efe5f3 before it
            for j in range(i-1,max(0,i-60),-1):
                if 'task-94efe5f3' in lines[j] and 'Test input' in lines[j]:
                    mm=re.search(r'Test input \((\d+)x(\d+)\)', lines[j])
                    out.append(('input', mm.groups() if mm else None))
                    break
    return out
